-- CAREEROS P3-T10: the customer details printed on an organization's invoices. The CREATE TABLE and foreign key
-- statements are generated by drizzle-kit; row-level security and grants are written by hand, following P3-T08 and
-- P5-T04. Runs as the migration (owner) role. Down migration: down.sql in this folder.
CREATE TABLE "organization_billing_profile" (
	"organization_id" text PRIMARY KEY,
	"legal_name" text,
	"address" text,
	"tax_pin" text,
	"billing_email" text,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" text,
	CONSTRAINT "organization_billing_profile_legal_name_check" CHECK (char_length("legal_name") <= 200),
	CONSTRAINT "organization_billing_profile_address_check" CHECK (char_length("address") <= 500),
	CONSTRAINT "organization_billing_profile_tax_pin_check" CHECK (char_length("tax_pin") <= 32),
	CONSTRAINT "organization_billing_profile_billing_email_check" CHECK (char_length("billing_email") <= 254 and "billing_email" ~ '^[^@[:space:][:cntrl:]<>,;]+@[^@[:space:][:cntrl:]<>,;]+$')
);
--> statement-breakpoint
ALTER TABLE "organization_billing_profile" ADD CONSTRAINT "organization_billing_profile_6QMO4D45Xrwn_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization"("id") ON DELETE CASCADE;--> statement-breakpoint
ALTER TABLE "organization_billing_profile" ADD CONSTRAINT "organization_billing_profile_updated_by_user_id_fkey" FOREIGN KEY ("updated_by") REFERENCES "user"("id") ON DELETE SET NULL;
--> statement-breakpoint
-- Row-level security (D4), exactly as P1-T04, P4-T01 and P5-T04: FORCE applies the policy to the table owner too, so
-- only owner_access lets the owner role (migrations, definer functions) see every organization. careeros_app only
-- matches its own organization; an unset setting is NULL and matches nothing (fail closed).
ALTER TABLE "organization_billing_profile" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "organization_billing_profile" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_isolation" ON "organization_billing_profile";--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "organization_billing_profile"
	USING ("organization_id" = current_setting('app.current_org_id', true))
	WITH CHECK ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "organization_billing_profile";--> statement-breakpoint
CREATE POLICY "owner_access" ON "organization_billing_profile" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
-- Table privileges for the app role: read, add and change a row, never delete one (the row goes with its organization
-- through the foreign key). The bootstrap's default privileges may already grant DELETE, so it is revoked; idempotent.
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		GRANT SELECT, INSERT, UPDATE ON "organization_billing_profile" TO careeros_app;
		REVOKE DELETE, TRUNCATE ON TABLE public.organization_billing_profile FROM careeros_app;
	END IF;
END $$;
